  "exports.eyebrow": "数据",
  "exports.title": "导出搭备份",
  "exports.subtitleStart": "下载永远只限于",
  "exports.subtitleRest": "。每个文件侪会标好生意名字搭做出来个日期。",
  "exports.createBusinessFirst": "先开一家生意——导出是属于生意个，勿是属于搿只应用个。",
  "exports.lockedTitle": "CSV 搭 Excel 导出是 Business 套餐个功能",
  "exports.lockedDesc": "侬个工作区现在是 Essentials 套餐。Business 加上 CSV 搭 Excel 导出、库存估值、无限产品搭员工、供应商、采购搭套装。",
  "exports.seeBusiness": "看看 Business 包括啥",
  "exports.whatTheseAre": "搿眼文件是啥",
  "exports.about1": "每份数据侪有 CSV 或者真正个 Excel 工作簿 (.xlsx)——完整库存工作簿只有 Excel 版，每份数据一张工作表。CSV 文件好勒 Excel、Numbers、Google Sheets 搭大多库存应用里向打开。UTF-8 文本、带引号个逗号、备注里向个换行搭编码开头个零侪会保留，单元格开头看上去像公式个，会处理成文本，电子表格打开就当文本看。",
  "exports.about2": "勒 Excel 文件里向，SKU、UPC、ISBN 搭条形码侪是文本单元格——永远勿会变成科学计数法，勿会削掉开头个零——列宽、表头筛选搭货币或者数量格式侪设置好了。完整库存工作簿拿产品、库存量、地点搭移动记录分勒弗同个工作表里向。",
  "exports.about3": "交关大个导出，每份数据最多 20,000 行——到仔搿个上限，文件名里向会讲清楚（truncated-20000），所以勿完整文件永远勿会当作完整文件。",
  "exports.about4": "备份是侬数据个快照，勿是一键恢复。恢复是一桩人工、要先检查个事体，所以文件要收好——应用里向呒没啥物事好从搿个文件重新造出一家已经删脱个生意。应用代码搭 Base44 平台个备份搭搿眼文件是分开处理个。",
  "exports.about5": "照片搭附件是列成伊拉存好个链接——图片文件本身勿会打包勒下载里向。",
  "exports.backupTitle": "完整备份",
  "exports.backupDesc": "一只文件，包括搿家生意个产品、地点、库存量、完整移动账本、供应商、采购、订单、退货、盘点搭上架——还有伊个资料设置。收勒侬自家控制得牢个地方。",
