  "print.chooseStyleHint": "先选一种样式，再从清单里向选产品。预览就是打印机里向出来个样子。",
  "print.howToReach": "哪能连到侬个打印机",
  "print.howIntro": "搿只应用连侬已经有个打印机——伊本身勿是一台打印机。有四种连法，标签两个套餐里向用哪种连法侪好印。装箱单、采购订单、供应商文件搭报表是 Business 专属，勿管用啥连法。",
  "print.howBluetoothLead": "Bluetooth。",
  "print.howBluetoothBody": "勒搿页上，桌面 Chrome 或者 Edge，还有 Android Chrome：选侬个标签打印机，标签就直接发过去了。iOS Safari 里向勿行——勒 iPhone 上，Bluetooth 打印是搭移动应用一道来个。只会讲 Zebra ZPL 或者 Brother 自家语言个打印机，听勿懂搿页发过去个标签；讲是好用之前，会拿真打印机对过。",
  "print.howWifiLead": "Wi-Fi。",
  "print.howWifiBody": "拿打印机装到侬店铺个 Wi-Fi 上，再用打印按钮——通过搿台电脑上装好个打印机，勒店铺网络里向打印。勒 iPhone 上，AirPrint 是自带个：同一 Wi-Fi 上个 AirPrint 打印机直接勒打印表里向出现，勿要线也勿要应用，应用勿需要专门为 AirPrint 写代码。打印机一定要支持 AirPrint（新个大多侪支持），手机搭打印机一定要勒同一个 Wi-Fi 上。",
  "print.howEthernetLead": "以太网。",
  "print.howEthernetBody": "用以太网线拿打印机连到店铺网络里向，勒电脑上装好，再通过打印按钮打印。以太网是桌面搭电脑个路子——iPhone 勿用以太网线。",
  "print.howUsbLead": "USB。",
  "print.howUsbBody": "用线拿打印机插到电脑上，再用打印按钮——通过搿台电脑上装好个打印机打印。勒 Android 手机上，用一根 USB OTG 线，上头个 USB 按钮直接搭打印机讲话。iPhone 勿好直接用 USB 打印——搿搭呒没 WebUSB——所以用 Wi-Fi / AirPrint，或者移动应用里向个 Bluetooth。",
  "print.howCordsLead": "线勒 iPhone 上还是有用个，只是多一步。",
  "print.howCordsBody": "一台 USB 打印机插勒店铺电脑上，或者一台以太网打印机连勒网络上，勒侬个 iPhone 上通过店铺 Wi-Fi（AirPrint / 共享打印机）就能看到——线拿打印机稳稳当当放勒网络上，手机再无线连过去。",
  "print.howOfflineLead": "要是断网了，",
  "print.howOfflineBody": "搿页上已经有个标签搭文件还是好印——打印按钮、标签 PDF、Bluetooth 搭 USB 侪勿需要联网。需要联网个，是头一趟加载搿页搭伊个产品。完整离线模式（完全勿联网勒应用里向做事）是另外一个更大个工程，搿搭勿讲伊已经有了。",
