  "settings.cancelTerms.graceTitle": "付费期结束之后——15 天宽限期，然后删除：",
  "settings.cancelTerms.intro": "搿是付费 Luminous StockHaven 订阅个条款。网站订阅通过 Stripe 收费。侬随时随地好自家用下头个“取消订阅”按钮取消订阅——勿需要员工批准。取消搭退款请求也可以通过官方客服联系方式处理：theluminousbookshop@outlook.com。",
  "settings.cancelTerms.noApprovalBody": "侬随时随地好自家取消订阅。勿需要员工批准。以后个续费只有勒账单方确认取消之后才会停脱。",
  "settings.cancelTerms.noApprovalTitle": "勿需批准就取消：",
  "settings.cancelTerms.paymentBody": "付费试用：七天试用勒注册辰光需要一张付款方式。除非勒适用个试用取消期限里向取消，否则试用结束之后会自动按选定个月度方案收费。价格、第一次账单日期搭各家特有个取消期限，注册辰光一定要显示出来。试用账单通过 Stripe 收费。",
  "settings.cancelTerms.paymentTitle": "付款方式搭自动续费：",
  "settings.cancelTerms.remainingBody": "如果侬已经为一个账单周期付过钱，侬好继续用到经过确认个付费到期日。提前结束需要账单方适当个确认搭相应个退款处理。免费试用个使用权按账单方确认个试用结束日期结束。",
  "settings.cancelTerms.remainingTitle": "剩余使用权：",
  "settings.cancelTerms.storesBody": "如果侬哪能通过 Google Play 或者 Apple App Store 订阅，订阅就由搿家商店收费搭管理。侬可能需要勒订阅用个同一个 Google 或者 Apple 账号个订阅栏目里向直接取消。取消另外一个网站订阅、卸载搿个应用，或者要求删除 Luminous StockHaven 账号，侪勿会自动取消商店收费个订阅。看看侬个购买收据，确认到底是哪家向侬收费。",
  "settings.cancelTerms.storesTitle": "Google Play 搭 Apple App Store 订阅（如果侬哪能通过商店订阅）：",
  "settings.cancelTerms.title": "取消条款与条件",
  "settings.cancelTerms.trialBody": "七天试用每个符合条件个顾客只好用一趟。取消试用或者订阅勿会再给一趟试用；回来个顾客一定要选付费订阅。",
