  "staff.access.suspendedBody": "管理员已经暂停脱搿个员工账号勒当前业务里向个使用。请伊拉拿侬改回有效，然后再登录。",
  "staff.access.suspendedTitle": "侬个使用权已暂停",
  "staff.addFirst": "添加第一位员工",
  "staff.addMember": "添加员工",
  "staff.emptyBody": "加一个人，给伊一个角色搭相应个权限，伊就会收到邮件邀请，登录搿家业务。",
  "staff.emptyTitle": "还没有员工",
  "staff.eyebrow": "团队",
  "staff.how.p1": "每位成员侪有一个角色搭自家个权限清单，所以侬好从角色起步，改脱一样物事，勿需要再建一个新角色。改角色勿会重写已经勒上头个成员——打开成员，重新套用伊个角色默认设置。",
  "staff.how.p2": "自定义角色是 Business 个功能：Essentials 用五个内置角色（店主、经理、库存员、销售员、查看者）。",
  "staff.how.p3": "邀请通过邮件发送。成员只有接受之后才能登录；从搿个名单里向删脱一个人，勿会删脱伊个应用账号。",
  "staff.how.p4": "店铺就是一个人被分到个地点。伊记勒伊个卡片上；伊好打开啥，还是由伊个角色搭权限决定。",
  "staff.how.p5": "权限决定每个人好打开啥：角色之外个菜单项会藏起来，勒一个被拦牢个地址上会显示“勿勒侬个角色上”个提示，勿是页面。改动勒搿个人下趟加载应用辰光生效；暂停成员会拿伊完全锁勒外头。",
  "staff.how.p6": "管理员好看搭改所有数据，管理应用用户搭角色，永远勿受员工角色限制。没员工记录个人——比方讲新业务个店主——照样有全部权限。",
  "staff.howTitle": "员工搭角色哪能运作",
