  "payroll.dd.steps.body": "1. 侬需要一个好发送 ACH 付款个生意银行账户。2. 向每位团队成员收集签名个授权表——作废支票有助于核对号码。3. 勒发薪日前2-3个工作日发送工资，以便款项按时到账。4. 大多数州要求团队成员个书面同意。搿只应用收集表格并引导侬完成步骤——实际汇款通过侬自己个银行进行。",
