  "training.warningSentOn": "警告发送于 {date}",
  "auth.sameEmailNotice": "已经从 Google Play 或 App Store 获得了阿拉个应用？请勒搿搭使用同一邮箱——侬登录应用所用个邮箱——搿能侬个店铺搭库存会随侬而来。使用勿同个邮箱会开启一个全新个、空个店铺。",
  "settings.deleteConfirmWord": "删除",
