  "workforce.tab.rewards": "奖励",
  "training.lessons.mgr-give-rewards.step1": "打开“员工管理”，点“奖励”。选择团队成员，然后选择类型：店内折扣百分比、礼品卡，或侬用自己个话描述个其他奖励。",
  "training.lessons.mgr-give-rewards.step2": "给奖励起一个简短名称，如愿意可加备注。搿个人员会立即收到铃铛通知，奖励会带着自己个验证码等勒伊个“我个奖励”里向。",
  "training.lessons.mgr-give-rewards.step3": "按设计个界限：侬只能奖励员工。侬勿能奖励自己或另一位经理——奖励经理是店主个决定，应用会直言拒绝。",
  "training.lessons.mgr-give-rewards.step4": "勒收银台，输入团队成员向侬出示个验证码并标记为已使用——每个验证码只能使用一次。如果计划有变，侬好作废自己发放个奖励；店主个礼物由店主作废。",
  "training.lessons.mgr-give-rewards.title": "向侬个员工发放奖励",
  "training.lessons.owner-give-rewards.step1": "奖励位于“员工管理”个“奖励”选项卡，且仅限 Business 套餐——勒 Essentials 里向，搿个选项卡显示一扇锁着个门，让侬个团队看到更大套餐包含啥。",
  "training.lessons.owner-give-rewards.step2": "侬好奖励团队里向个啥人——员工搭经理侪好。选择人员，然后选择类型：店内折扣百分比（侬选择个任意百分比）、任意地方个礼品卡，或侬用自己个话描述个任意激励。",
  "training.lessons.owner-give-rewards.step3": "奖励会带着自己个一次性验证码到达，并提醒搿个人员个铃铛。伊拉勒收银台出示验证码；店主或经理输入伊以标记为已使用。",
  "training.lessons.owner-give-rewards.step4": "打印或共享个奖励小票只带有侬生意个名称——绝勿带应用个名称。搿是侬店铺个感谢，勿是广告。",
  "training.lessons.owner-give-rewards.title": "发放奖励（Business 套餐）",
  "training.lessons.owner-rewards-oversight.step1": "侬个经理也好发放奖励——仅限员工。应用会拒绝经理奖励自己或另一位经理；奖励经理始终是侬个决定。",
  "training.lessons.owner-rewards-oversight.step2": "侬好勒“奖励历史”中看到生意里向个每份奖励：谁发放个、谁收到个，搭伊是可用、已使用还是已作废。经理只能看到自己发放个搭自己收到个奖励。",
  "training.lessons.owner-rewards-oversight.step3": "侬好作废任意奖励，包括侬个经理发放个。经理好作废自己个礼物，但永远勿能作废侬个。",
  "training.lessons.owner-rewards-oversight.step4": "每个验证码只能使用一次，作废个奖励永远勿能使用——历史始终显示一份奖励个最终结果。",
  "training.lessons.owner-rewards-oversight.title": "监管奖励：侬经理个发放",
  "training.lessons.staff-your-rewards.step1": "当侬个经理或店主给侬发放奖励时，侬个铃铛会响。打开“员工管理”，点“奖励”，勒“我个奖励”下查看伊。",
  "training.lessons.staff-your-rewards.step2": "每份奖励侪有自己个验证码。请自己保管——勒收银台出示验证码个人就是使用搿个奖励个人。",
  "training.lessons.staff-your-rewards.step3": "要使用伊，请勒购买时出示验证码。收银台个人会输入伊并标记为已使用——每个验证码只能使用一次。",
  "training.lessons.staff-your-rewards.step4": "奖励是 Business 套餐个福利。如果侬个店铺勿勒 Business 套餐里向，“奖励”选项卡会显示一扇锁着个门——那是套餐个原因，勿是错误。",
  "training.lessons.staff-your-rewards.title": "侬个奖励：寻到验证码并使用伊",
  "training.module.rewards": "奖励搭激励",
