  "plansLib.includes.support": "应用内问题报告",
  "support.category.broken": "有东西坏了",
  "support.category.idea": "想法或建议",
  "support.category.looksWrong": "有东西看起来勿对",
  "support.category.other": "其他",
  "support.categoryLabel": "搿是关于啥个？",
  "support.contextNote": "为了帮阿拉寻到问题，侬个留言会自动包含侬所勒个页面、侬选择个生意搭角色、侬个套餐、应用语言，搭侬使用个手机或浏览器类型。伊永远勿会包含侬个产品、库存或销售。",
  "support.description": "有东西坏了、有东西看起来勿对，或有想法要分享？请勒搿搭告诉阿拉——侬个留言会直接发给应用背后个团队。",
  "support.errorGeneric": "操作未成功。请重试。",
  "support.errorRateLimit": "侬今天已发送了几份报告——谢谢。请等到明天再发送更多，以便每份报告侪能被认真阅读。",
  "support.errorTooLong": "搿超出了报告可容纳个长度——请稍微删减后重新发送。",
  "support.errorTooShort": "请多告诉阿拉一点——一两句话有助于阿拉寻到问题。",
  "support.messageLabel": "发生了啥？",
  "support.messagePlaceholder": "用侬自己个话告诉阿拉侬当时勒做啥、出了啥问题…",
  "support.sendAnother": "再发送一份报告",
  "support.sending": "正在发送…",
  "support.sentBody": "阿拉会阅读每份报告。如果需要更多详情，阿拉会写信到侬个账号邮箱。",
  "support.sentTitle": "谢谢——侬个报告已发送。",
  "support.submit": "发送报告",
  "support.title": "报告问题",
  "support.urgentNote": "是被锁勒账号外头了？侬个备用钥匙好帮侬回来——见上头个“安全搭备用钥匙”，或使用登录页面上个恢复入口。",
  "training.lessons.mgr-report-problem.step1": "侬个团队勒收银台工作，问题最先勒迭搭出现。如果应用对侬团队里向个啥人出现故障或行为异常，好当场从“设置”个“报告问题”进行报告——由伊拉或由侬报告。",
  "training.lessons.mgr-report-problem.step2": "请让伊拉讲清楚经过：伊拉当时勒做啥、期望啥、实际发生了啥。一两句搿能个描述胜过事后完美个描述。",
  "training.lessons.mgr-report-problem.step3": "报告会自行附上页面、店铺、发送者个角色、套餐、应用语言搭设备类型；产品、库存搭销售永远勿会附上。店铺个任意数字侪勿会随报告离开。",
  "training.lessons.mgr-report-problem.step4": "报告会发给应用背后个团队，每一份侪会被阅读。如果问题把某人锁勒账号外，勿要等待报告：备用钥匙搭登录页面个恢复入口能让伊拉回来。",
  "training.lessons.mgr-report-problem.title": "当侬个团队遇到问题时：报告伊，勿要绕过伊",
  "training.lessons.owner-report-problem.step1": "侬个订阅包含一条搭构建搿只应用个人直接联系个渠道。打开“设置”，使用“报告问题”——伊勒每个套餐中侪有，为侬搭侬团队个每位成员提供。",
  "training.lessons.owner-report-problem.step2": "用侬自己个话说明发生了啥：侬当时想做啥，应用却做了啥。表单会自行附上修复所需个详情——页面、生意、角色、套餐、语言搭设备；侬个产品、库存搭销售永远勿会包含勒里向。",
  "training.lessons.owner-report-problem.step3": "每份报告侪会被保存并由团队阅读。如果更多详情有帮助，伊拉会回复发送者个账号邮箱——搿能答复能到达看到问题个人。",
  "training.lessons.owner-report-problem.step4": "一个例外：如果侬或团队成员完全呒没办法进入账号，报告勿是最快个入口。备用钥匙（设置、安全搭备用钥匙）搭登录页面上个恢复入口正是为搿种情况准备个。",
  "training.lessons.owner-report-problem.title": "报告问题：侬搭应用团队个直通线",
  "training.lessons.report-problem.step1": "如果应用中有东西坏了、看起来勿对，或感觉勿对，侬勿必忍受伊。打开“设置”，寻到“报告问题”——伊为每个人提供，勒每个套餐中侪有。",
  "training.lessons.report-problem.step2": "选择侬个留言是关于啥个——有东西坏了、有东西看起来勿对、一个想法，或其他——然后用侬自己个话写下发生了啥。侬当时勒做啥最有帮助。",
  "training.lessons.report-problem.step3": "侬个留言会自动带有侬所勒个页面、侬个店铺搭角色、套餐、应用语言，搭侬使用个手机或浏览器类型——帮助寻到问题个详情。伊永远勿会带有侬个产品、库存或销售。",
  "training.lessons.report-problem.step4": "发送伊，伊会直接发给应用背后个团队，伊拉会阅读每份报告。如果伊拉需要更多详情，伊拉会写信到侬个账号邮箱。是被锁勒账号外头了？请使用侬个备用钥匙或登录页面上个恢复入口——迭眼比报告更快。",
  "training.lessons.report-problem.title": "报告问题：有东西坏了就告诉阿拉",
  "crossStore.transferButton": "搬库存",
  "crossStore.transferChooseProduct": "拣一个产品…",
  "crossStore.transferFailed": "迭趟搬货呒没成功。",
  "crossStore.transferFromLocation": "从啥地方",
  "crossStore.transferIntro": "两家店侪是侬个，所以侬可以直接搬库存，用勿着申请。拣一个产品，讲清爽几许搭从啥地方出发，再拣伊到哪家店。两家店会马上更新，而且侪会留脱迭趟搬货个记录。",
  "crossStore.transferNoTargets": "侬还呒没另外一家属于侬个店——库存只好勒属于侬个店之间搬来搬去。",
  "crossStore.transferOnHand": "现有 {count} 件",
  "crossStore.transferProduct": "产品",
  "crossStore.transferQuantity": "数量",
  "crossStore.transferSuccess": "已经拿 {quantity} × {product} 搬到 {store} 哉。",
  "crossStore.transferTarget": "搬到",
  "crossStore.transferTitle": "拿库存搬到另外一家店",
  "crossStore.transferToFirstLocation": "伊个第一个地方",
  "crossStore.transferToLocation": "到啥地方",
  "training.lessons.owner-move-stock.step1": "申请是用来请求个；搬货是老板个事体。勒跨店收件箱页面，“搬库存”面板让侬——老板——拿库存直接从迭家店送到侬拥有个另外一家店，用勿着申请，也用勿着等。",
  "training.lessons.owner-move-stock.step2": "拣产品、伊出发个地方搭数量。应用会显示搿个地方有几许库存，一趟搬货绝对勿可以超过迭个数目。",
  "training.lessons.owner-move-stock.step3": "拣目标店，假使愿意，还可以拣伊勒伊面个确切地方。假使伊家店已经有相同个 SKU，库存会并进伊个产品；假使呒没，产品会搭库存一道复制过去。",
  "training.lessons.owner-move-stock.step4": "两家店侪会留脱记录：迭家店显示转出，另外一家显示接收。假使搬勿动——库存勿够，或者另外一家店勿是侬个——啥侪勿会搬，应用会讲明原因。",
  "training.lessons.owner-move-stock.title": "勒侬自家个店之间搬库存（Business 计划）",
  "plansLib.feature.pricing": "清仓搭限时特价定价",
  "plansLib.includes.pricing": "清仓搭限时特价个销售定价",
